class DomainCompanies(DiscolikeRequest):
    source: Annotated[Literal["domains"], Field(title="Source")]
    domains: Annotated[
        list[str],
        Field(description="Company domains to find contacts at.", max_length=10000, min_length=1, title="Domains"),
    ]
    scores: Annotated[
        dict[str, float] | None,
        Field(description="Optional relevance score per domain, keyed by domain.", title="Scores"),
    ] = None


class FindMissingSpec(DiscolikeRequest):
    search_provider_id: Annotated[str | None, Field(title="Search Provider Id")] = None
    enabled: Annotated[
        bool | None, Field(description="Search for contacts at companies where none were found.", title="Enabled")
    ] = True
    provider: Annotated[
        str | None,
        Field(description="'discolike' uses DiscoLike search; an integration id uses your own keys.", title="Provider"),
    ] = "discolike"


class LookalikeCompanies(DiscolikeRequest):
    source: Annotated[Literal["lookalike"], Field(title="Source")]
    persona_ids: Annotated[
        list[int],
        Field(description="Personas whose companies seed the lookalike search.", min_length=1, title="Persona Ids"),
    ]


class PeopleSpec(DiscolikeRequest):
    titles: Annotated[
        list[str] | None,
        Field(
            description="Job titles of the people to find. Optional for a lookalike run, which then uses the seeds' titles.",
            max_length=50,
            title="Titles",
        ),
    ] = None
    exclude_titles: Annotated[
        list[str] | None, Field(description="Job titles to leave out.", title="Exclude Titles")
    ] = None
    match: Annotated[
        Literal["similar", "exact"] | None,
        Field(description="'similar' also accepts close variants of a title; 'exact' does not.", title="Match"),
    ] = "similar"


