class ContinueRunRequest(DiscolikeRequest):
    generation: Annotated[
        int, Field(description="Generation of the run you are continuing, as last returned.", title="Generation")
    ]
    relevance: Annotated[
        Literal["max_relevance", "balanced", "max_coverage"] | None,
        Field(description="Change the relevance setting.", title="ContactsRelevance"),
    ] = None
    not_fit_ids: Annotated[
        list[str] | None, Field(description="Ids of rows to drop as not a fit.", title="Not Fit Ids")
    ] = None
    email_cap_usd: Annotated[
        Annotated[Decimal, Field(ge=0)] | None,
        Field(description="Maximum spend in USD on finding emails.", title="Email Cap Usd"),
    ] = None
    redo: Annotated[bool | None, Field(description="Run the current step again.", title="Redo")] = False
    target_step: Annotated[
        Literal["find_missing"] | None,
        Field(description="Return from review to find missing in a new generation.", title="Target Step"),
    ] = None


class PromptCompanies(DiscolikeRequest):
    max_companies: Annotated[int | None, Field(ge=1, le=10000, title="Max Companies")] = 500
    source: Annotated[Literal["prompt"], Field(title="Source")]
    icp_text: Annotated[
        str, Field(description="Plain-language description of the companies you want.", min_length=3, title="Icp Text")
    ]
    filters: Annotated[
        PromptCompanyFilters | None, Field(description="Company filters applied on top of the description.")
    ] = None


class ContactsRunRequest(DiscolikeRequest):
    start: Annotated[bool | None, Field(title="Start")] = True
    exclude_query_ids: Annotated[list[str] | None, Field(max_length=20, title="Exclude Query Ids")] = None
    exclude_domains: Annotated[list[str] | None, Field(max_length=100, title="Exclude Domains")] = None
    companies: Annotated[
        PromptCompanies | DomainCompanies | LookalikeCompanies, Field(discriminator="source", title="Companies")
    ]
    people: PeopleSpec
    relevance: Annotated[
        Literal["max_relevance", "balanced", "max_coverage"] | None,
        Field(description="Trade-off between contact relevance and coverage.", title="ContactsRelevance"),
    ] = "balanced"
    per_company: Annotated[
        Annotated[int, Field(ge=1, le=50)] | Literal["all"] | None,
        Field(description="Maximum contacts per company, or 'all'.", title="Per Company"),
    ] = 10
    find_missing: FindMissingSpec | None = None
    email_cap_usd: Annotated[
        Annotated[Decimal, Field(ge=0)] | None,
        Field(description="Maximum spend in USD on finding emails. No cap when omitted.", title="Email Cap Usd"),
    ] = None
    mode: Annotated[
        Literal["step_by_step", "run_all"] | None,
        Field(description="'step_by_step' pauses for review between steps; 'run_all' does not.", title="Mode"),
    ] = "step_by_step"
    create_key: Annotated[
        str | None,
        Field(
            description="Idempotency key: repeating a request with the same key returns the same run.",
            title="Create Key",
        ),
    ] = None


